// نستخدم غربال إراتوستينس لكفاءته في توليد الأعداد الأولية
function sieve(n) {
  const isPrime = new Array(n + 1).fill(true);
  isPrime[0] = isPrime[1] = false;
  for (let i = 2; i * i <= n; i++) {
    if (isPrime[i]) {
      for (let j = i * i; j <= n; j += i) isPrime[j] = false;
    }
  }
  return isPrime.reduce((acc, val, idx) => val ? acc.concat(idx) : acc, []);
}

