// لماذا: الطابور يحاكي وصول العمليات بنظام FIFO كما في جدولة Round Robin
class Queue {
  constructor() {
    this.items = [];
  }
  enqueue(item) { this.items.push(item); }
  dequeue() { return this.items.shift(); }
  isEmpty() { return this.items.length === 0; }
}

const processes = [
  { name: 'P1', burst: 5 },
  { name: 'P2', burst: 3 },
  { name: 'P3', burst: 8 }
];
const quantum = 4;
const queue = new Queue();
processes.forEach(p => queue.enqueue(p));
const order = [];
while (!queue.isEmpty()) {
  const current = queue.dequeue();
  if (current.burst > quantum) {
    order.push(current.name);
    current.burst -= quantum;
    queue.enqueue(current);
  } else {
    order.push(current.name);
  }
}
console.log('Execution order:', order.join(' -> '));

