// لماذا: المكدّس مثالي لتتبع الأقواس المفتوحة بترتيب LIFO
function isBalanced(expression) {
  const stack = [];
  const pairs = { ')': '(', ']': '[', '}': '{' };
  for (const ch of expression) {
    if (['(', '[', '{'].includes(ch)) {
      stack.push(ch);
    } else if ([')', ']', '}'].includes(ch)) {
      if (stack.length === 0 || stack.pop() !== pairs[ch]) return false;
    }
  }
  return stack.length === 0;
}

