const memo = {};
function fib(n) {
  // نعيد القيمة المحفوظة لتجنب إعادة الحساب المكرر
  if (n in memo) return memo[n];
  if (n <= 1) return n;
  memo[n] = fib(n - 1) + fib(n - 2);
  return memo[n];
}
console.log(fib(10));

